            self::term('البند السابع: الجوانب المالية:', 7, 3, 'يحق للطرف الأول اتخاذ كافة الإجراءات النظامية للجهات المختصة للمطالبة بالمبالغ المستحقة في حال عدم سداد الطرف الثاني المبالغ المستحقة خلال (3) ثلاثة أيام من تاريخ الاستحقاق المذكور في الجدول.', 8, 5),
            self::term('البند السابع: الجوانب المالية:', 7, 4, 'يلتزم الطرف الثاني بدفع الآتي:', 9, 5),

