    private static function term(string $sectionTitle, int $sectionOrder, ?int $termNumber, string $content, int $termOrder, int $pageNumber): array
    {
        return [
            'section_title' => $sectionTitle,
            'section_order' => $sectionOrder,
            'term_number' => $termNumber,
            'term_content' => $content,
            'term_order' => $termOrder,
            'page_number' => $pageNumber,
            'is_active' => true,
        ];
    }
}
